
import type { ShippingDimensionsInput } from './ShippingDimensionsInput.js';
import type { ShippingWeightInput } from './ShippingWeightInput.js';

export type PackageInput = { "carrier"?: string; /** Creation timestamp. Format: date-time. */ "created_at"?: never; /** Package delivery timestamp. Format: date-time. */ "delivered_at"?: never; "dimensions"?: ShippingDimensionsInput; /** Caller-owned identifier for this resource in an external system. Caller-owned package identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. maxLength: 255. */ "external_reference_id"?: string; /** External carrier, aggregator, or fulfillment platform name for this package. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string; "fulfillment_id"?: never; /** Merchant or integration supplied HTTPS shipping-label URL for authenticated merchant workflows. Non-Flint URLs must include external_system for provenance. Flint does not currently manage label file hosting or buyer-facing label downloads. */ "label_url"?: string; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; "package_id"?: never; /** Return this package belongs to. Present only on packages of return shipments. */ "return_id"?: never; /** Return line quantities allocated to this parcel. Present only on packages of return shipments. */ "return_line_items"?: never; "service_code"?: string; "shipment_id"?: never; /** Package handoff timestamp. Format: date-time. */ "shipped_at"?: never; /** Current package lifecycle state. Package states are the source used to derive shipment status. - `created`: The package record exists but has not been packed or handed off. - `packed`: The package is packed and awaiting carrier handoff. - `shipped`: The package was handed to the carrier. - `in_transit`: The carrier is moving the package through its network. - `out_for_delivery`: The package is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The package was returned toward or to its origin. - `voided`: The package was voided and will not continue through delivery. */ "status"?: never; "status_reason"?: string; /** Read-only actions currently supported for this package. */ "supported_actions"?: never; "tracking_number"?: string; /** Absolute HTTPS carrier tracking URL. Embedded URL credentials are rejected. */ "tracking_url"?: string; /** Last update timestamp. Format: date-time. */ "updated_at"?: never; /** Monotonic package version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version"?: never; "weight"?: ShippingWeightInput; };
